with valid as (select *, coalesce(quantity, 0) as quantity_filled from inventory where last_restock > date '2023-08-12') select case when quantity >= 210 then 'HIGH' else 'LOW' end as quantity_tier, stddev_samp(quantity) as quantity_stddev, count(distinct store_id) as distinct_store_ids, count(*) as row_count, percentile_approx(quantity_filled, 0.5) as quantity_filled_p50, round(avg(quantity), 2) as avg_quantity, count(distinct product_id) as distinct_product_ids from valid group by 1 having percentile_approx(quantity_filled, 0.5) > 0 order by distinct_product_ids desc
